634	    /// it stands for (`(value?: string) => void`, not `Handler`), and a long type is printed to its end.
635	    pub(crate) async fn type_to_string_expanded(&self, type_id: u64) -> Result<String, CallError> {
636	        self.scoped("typeToString", json!({ "type": type_id, "flags": flag::PRINT_EXPANDED })).await
637	    }
638	
639	    pub(crate) async fn documentation(&self, symbol: &Value) -> Result<String, CallError> {
640	        self.scoped("getDocumentationComment", json!({ "symbol": symbol })).await
641	    }
642	}
643	
644	fn default_options() -> Value {
645	    // Numeric enum values: JSX preserve, ESNext modules, bundler resolution, ES2022.
646	    json!({ "jsx": 1, "module": 99, "moduleResolution": 100, "target": 9, "strict": true, "skipLibCheck": true, "noEmit": true })
647	}
648	
649	/// An answer parsed from its text straight into `T`, in one pass.
650	pub(crate) fn decode<T: DeserializeOwned>(answer: &RawValue) -> Result<T, CallError> {
651	    serde_json::from_str(answer.get())
652	        .map_err(|error| CallError::Rejected(format!("unexpected response shape: {error}")))
653	}
654	
655	#[cfg(test)]
656	mod tests {
657	    use super::*;
658	
659	    #[test]
660	    fn a_name_with_three_or_more_leading_underscores_loses_the_one_the_checker_added() {
661	        assert_eq!(unescape_leading_underscores("___size"), "__size");
662	        assert_eq!(unescape_leading_underscores("____triple"), "___triple");
663	        assert_eq!(unescape_leading_underscores("___0"), "__0");
664	    }
665	
666	    #[test]
667	    fn other_names_are_unchanged() {
668	        for name in ["size", "_single", "__call", "__type", "default", "", "a___b"] {
669	            assert_eq!(unescape_leading_underscores(name), name);
670	        }
671	    }
672	
673	    #[test]
674	    fn a_symbol_arrives_with_the_name_the_source_writes() {
675	        let symbol: SymbolInfo =
676	            serde_json::from_value(json!({ "reference": {}, "name": "___size", "flags": 0 })).unwrap();
677	
678	        assert_eq!(symbol.name, "__size");
679	    }
680	}
