300	    /// Initializes the `tsc` session and reads the compiler options, once per process. The beta panics on
301	    /// string-valued enum options such as `target: "es2022"`, so options come from `parseConfigFile`, which yields
302	    /// numeric ones.
303	    pub(crate) async fn prepare(
304	        client: &Client,
305	        deadline: Duration,
306	        tsconfig: Option<&str>,
307	    ) -> Result<Value, CallError> {
308	        let rpc = Rpc {
309	            client: client.clone(),
310	            deadline,
311	            snapshot: 0,
312	            project: String::new(),
313	            options: Value::Null,
314	            recording: None,
315	            calls: Arc::default(),
316	        };
317	        rpc.call("initialize", Value::Null).await?;
318	        Ok(match tsconfig {
319	            Some(file) => {
320	                let parsed: Value = decode(&rpc.call("parseConfigFile", json!({ "file": file })).await?)?;
321	                parsed.get("options").cloned().unwrap_or_else(default_options)
322	            }
323	            None => default_options(),
324	        })
325	    }
326	
327	    /// A snapshot over `root_files` in a session [`Rpc::prepare`] already initialized.
328	    pub(crate) async fn open_with(
329	        client: Client,
330	        deadline: Duration,
331	        options: &Value,
332	        root_files: &[String],
333	        record: bool,
334	    ) -> Result<Rpc, CallError> {
335	        let rpc = Rpc {
336	            client,
337	            deadline,
338	            snapshot: 0,
339	            project: String::new(),
340	            options: options.clone(),
341	            recording: record.then(Arc::default),
342	            calls: Arc::default(),
343	        };
344	        rpc.created(json!({ "createPrograms": [{ "rootFiles": root_files, "compilerOptions": options }] })).await
345	    }
346	
347	    /// A new snapshot of the same program with `files` added, held in the checker's memory and never written to disk:
348	    /// each is a root file, keyed by its absolute path. The calls on it count, and are recorded, with this one's.
349	    pub(crate) async fn layered(&self, root_files: &[String], files: &[(String, String)]) -> Result<Rpc, CallError> {
350	        let rpc = Rpc {
351	            client: self.client.clone(),
352	            deadline: self.deadline,
353	            snapshot: 0,
354	            project: String::new(),
355	            options: self.options.clone(),
356	            recording: self.recording.clone(),
357	            calls: self.calls.clone(),
358	        };
359	        let mut roots = root_files.to_vec();
360	        roots.extend(files.iter().map(|(path, _)| path.clone()));
361	        let layer: serde_json::Map<String, Value> =
362	            files.iter().map(|(path, text)| (path.clone(), Value::String(text.clone()))).collect();
363	        rpc.created(json!({
364	            "fileSystem": { "kind": "layer", "files": layer },
365	            "createPrograms": [{ "rootFiles": roots, "compilerOptions": self.options }],
366	        }))
367	        .await
368	    }
369	
370	    /// The snapshot after this one with `changed` and `deleted` read again from the disk and, given `roots`, its program
371	    /// rooted there instead, built at once (`updateSnapshot` with `ensurePrograms`). Files the program has not changed
372	    /// are kept as parsed: the checker re-reads only what it is told about, and a synthetic program sees even that
373	    /// only when it is rebuilt. This snapshot stays alive until it is released.
374	    pub(crate) async fn updated(
375	        &self,
376	        changed: &[String],
377	        deleted: &[String],
378	        roots: Option<&[String]>,
379	    ) -> Result<Rpc, CallError> {
380	        let mut changes = serde_json::Map::new();
381	        if !changed.is_empty() || !deleted.is_empty() {
382	            changes.insert("fileNotifications".to_string(), json!({ "changed": changed, "deleted": deleted }));
383	        }
384	        if let Some(roots) = roots {
385	            changes.insert(
386	                "reconfigurePrograms".to_string(),
387	                json!([{ "id": self.project, "rootFiles": roots, "compilerOptions": self.options }]),
388	            );
389	        }
390	        changes.insert("ensurePrograms".to_string(), Value::Bool(true));
391	        let response: SnapshotResponse =
392	            decode(&self.call("updateSnapshot", json!({ "snapshot": self.snapshot, "changes": changes })).await?)?;
393	        // The response lists only the projects it replaced; the synthetic program keeps its id.
394	        let project = response.projects.into_iter().next().map_or_else(|| self.project.clone(), |project| project.id);
395	        Ok(Rpc {
396	            client: self.client.clone(),
397	            deadline: self.deadline,
398	            snapshot: response.snapshot,
399	            project,
400	            options: self.options.clone(),
401	            recording: self.recording.clone(),
402	            calls: Arc::default(),
403	        })
404	    }
