439	    /// One request, its answer as the JSON text it arrived as: [`decode`] parses it once, into the shape the caller
440	    /// expects.
441	    async fn call(&self, method: &str, params: Value) -> Result<Box<RawValue>, CallError> {
442	        if let Ok(mut calls) = self.calls.lock() {
443	            *calls.entry(method.to_string()).or_default() += 1;
444	        }
445	        REQUESTS.try_with(|count| count.fetch_add(1, std::sync::atomic::Ordering::Relaxed)).ok();
446	        let Some(log) = &self.recording else {
447	            return Ok(self.client.request_raw(method, params, self.deadline).await.map_err(classify)?.result);
448	        };
449	        let answer = self.client.request_raw(method, params.clone(), self.deadline).await.map_err(classify)?;
450	        let result: Value = decode(&answer.result)?;
451	        if let Ok(mut log) = log.lock() {
452	            log.push(json!({ "method": method, "params": params, "result": result }));
453	        }
454	        Ok(answer.result)
455	    }
