546	    /// Several requests in one round trip. A request the checker rejects fails the batch: nothing here asks for one
547	    /// that may legitimately fail.
548	    pub(crate) async fn batch(&self, requests: Vec<(&str, Value)>) -> Result<Vec<Box<RawValue>>, CallError> {
549	        let wanted = requests.len();
550	        let scoped: Vec<Value> = requests
551	            .into_iter()
552	            .map(|(method, mut params)| {
553	                if let Value::Object(map) = &mut params {
554	                    map.insert("snapshot".to_string(), json!(self.snapshot));
555	                    map.insert("project".to_string(), json!(self.project));
556	                }
557	                json!({ "method": method, "params": params })
558	            })
559	            .collect();
560	        let mut answers = Vec::with_capacity(wanted);
561	        let mut token: Option<String> = None;
562	        loop {
563	            let mut params = json!({ "requests": scoped });
564	            if let (Some(token), Some(map)) = (&token, params.as_object_mut()) {
565	                map.insert("continuationToken".to_string(), json!(token));
566	            }
567	            let page: BatchPage = decode(&self.call("batchRequests", params).await?)?;
568	            for response in page.responses {
569	                if let Some(error) = response.error {
570	                    return Err(CallError::Rejected(error));
571	                }
572	                answers.push(response.result.unwrap_or_else(|| RawValue::NULL.to_owned()));
573	            }
574	            match page.continuation_token {
575	                Some(next) => token = Some(next),
576	                None => break,
577	            }
578	        }
579	        if answers.len() != wanted {
580	            return Err(CallError::Rejected(format!("a batch of {wanted} requests got {} answers", answers.len())));
581	        }
582	        Ok(answers)
583	    }
