// Throwaway spike (not committed): what the 7.1 protocol says about a prop's declaration, parent, tags and bases.
import { join } from 'node:path'
import { SymbolFlags } from 'typescript-beta/sync'

const proj = '/Users/gabe/Projects/caliper-fixtures/s7a-spike/proj'
const which = process.argv[2] ?? 'go'
const mod: any = which === 'go' ? await import('typescript-beta/sync') : await import('tsrs/sync')
const api = new mod.API({ cwd: proj })
const { options } = api.parseConfigFile(join(proj, 'tsconfig.json'))
const program = api.createProgram([join(proj, 'Button.tsx')], options)
const { checker } = program.getProject()
const file = join(proj, 'Button.tsx')
const moduleSymbol = checker.getSymbolOfSourceFile(file)
for (const exported of checker.getExportsOfModule(moduleSymbol)) {
  if (!(exported.flags & SymbolFlags.Function)) continue
  const type = checker.getTypeOfSymbol(exported)
  const [sig] = checker.getSignaturesOfType(type, 0)
  const props = checker.getTypeOfSymbol(sig.getParameters()[0])
  console.log(`== ${exported.name} props flags=${props.flags} objectFlags=${props.objectFlags}`)
  const bases = checker.getBaseTypes(props)
  console.log('  bases:', bases?.map((b: any) => checker.typeToString(b)))
  for (const prop of checker.getPropertiesOfType(props)) {
    if (!['tone', 'count', 'size', 'label', 'flag', 'inline', 'x', 'onClick', 'id'].includes(prop.name)) continue
    const raw = prop.declarations?.map((d: any) => String(d.id ?? d.handle ?? d))
    const parent = checker.getParentOfSymbol?.(prop)
    const tags = checker.getJsDocTags(prop)
    const doc = checker.getDocumentationComment(prop)
    const node = prop.declarations?.[0]?.resolve?.()
    const parentNode = node?.parent
    const t = checker.getTypeOfSymbol(prop)
    const members = t.flags & (1 << 27) ? checker.getTypesOfType(t).map((m: any) => checker.typeToString(m)) : []
    console.log(
      JSON.stringify({
        name: prop.name,
        raw,
        parentSym: parent ? { name: parent.name, flags: parent.flags, decl: parent.declarations?.map(String) } : null,
        tags,
        doc,
        nodeKind: node?.kind,
        nodePos: node && [node.pos, node.end],
        parentNodeKind: parentNode?.kind,
        parentName: parentNode?.name?.text,
        parentFile: parentNode?.getSourceFile?.()?.fileName,
        members,
      }),
    )
  }
}
