"""S7a counts: parent/declarations/tags coverage over unique props, composes over components, and gate-large's
checker-only props. usage: count.py <out dir> <label>"""
import json
import sys
from pathlib import Path


def load(path):
    return json.loads(Path(path).read_text())


def flat(doc, component):
    props = component['props']
    if isinstance(props, dict):
        return props
    merged = {}
    for set_id in props:
        merged.update(doc['propSets'][set_id])
    return merged


def names(doc, value):
    return doc['nameLists'][value] if isinstance(value, str) else (value or [])


def resolved_keys(doc):
    keys = set()
    for diagnostic in doc.get('diagnostics', []):
        if 'resolved by the TypeScript checker' in diagnostic.get('message', ''):
            keys.update(names(doc, diagnostic.get('affects')))
    return keys


def coverage(doc, label):
    props = doc['props']
    total = len(props)
    parent = sum(1 for p in props.values() if p.get('parent'))
    declarations = sum(1 for p in props.values() if p.get('declarations'))
    tags = sum(1 for p in props.values() if p.get('tags'))
    components = doc['components']
    composes = sum(1 for c in components.values() if c.get('composes'))
    resolved = resolved_keys(doc)
    in_resolved = set()
    for key in resolved:
        if key in components:
            in_resolved.update(flat(doc, components[key]).values())
    resolved_parent = sum(1 for i in in_resolved if props[i].get('parent'))
    print(f'{label}: unique props {total}, parent {parent}, declarations {declarations}, tags {tags}; '
          f'components {len(components)}, composes {composes}; checker-resolved {len(resolved)} components with '
          f'{len(in_resolved)} unique props, {resolved_parent} with parent')


def checker_only(structural, checker, label):
    only, without_parent, examples = 0, 0, []
    for key, component in checker['components'].items():
        base = structural['components'].get(key)
        base_names = set(flat(structural, base)) if base else set()
        for name, prop_id in flat(checker, component).items():
            if name in base_names:
                continue
            only += 1
            if not checker['props'][prop_id].get('parent'):
                without_parent += 1
                if len(examples) < 5:
                    examples.append(f'{key}.{name}')
    print(f'{label}: gate-large props only the checker returns {only}, without parent {without_parent} {examples}')


out, label = Path(sys.argv[1]), sys.argv[2]
coverage(load(out / f'spectrum.{label}.checker.json'), f'spectrum checker [{label}]')
gate_checker = load(out / f'gate.{label}.checker.json')
coverage(gate_checker, f'gate-large checker [{label}]')
checker_only(load(out / f'gate.{label}.structural.json'), gate_checker, label)

