// Throwaway spike (not committed): the raw protocol answers caliper's Rust client would get.
import { join } from 'node:path'

const proj = '/Users/gabe/Projects/caliper-fixtures/s7a-spike/proj'
const which = process.argv[2] ?? 'go'
const mod: any = which === 'go' ? await import('typescript-beta/sync') : await import('tsrs/sync')
const api = new mod.API({ cwd: proj })
api.parseConfigFile(join(proj, 'tsconfig.json'))
const client = (api as any).client
const req = (method: string, params: any) => client.apiRequest(method, params)
const { options } = req('parseConfigFile', { file: join(proj, 'tsconfig.json') })
const snap = req('createSnapshot', { createPrograms: [{ rootFiles: [join(proj, 'Button.tsx')], compilerOptions: options }] })
const scope = { snapshot: snap.snapshot, project: snap.projects[0].id }
const s = (method: string, params: any) => req(method, { ...scope, ...params })
const names = s('getSourceFileNames', {})
console.log('sourceFileNames sample:', names.filter((n: string) => !n.includes('lib.')).slice(0, 5))
const module = s('getSymbolOfSourceFile', { file: join(proj, 'Button.tsx') })
const exports = s('getExportsOfModule', { symbol: module.reference })
for (const exported of exports) {
  if (exported.name !== 'Button' && exported.name !== 'Card') continue
  const t = s('getTypeOfSymbol', { symbol: exported.reference })
  const [sig] = s('getSignaturesOfType', { type: t.id, kind: 0 })
  const [param] = s('getParametersOfSignature', { objectId: sig.id })
  const props = s('getTypeOfSymbol', { symbol: param.reference })
  const properties = s('getPropertiesOfType', { type: props.id })
  for (const p of properties) {
    if (!['tone', 'size', 'onClick', 'label', 'children'].includes(p.name)) continue
    console.log(`-- ${exported.name}.${p.name}`, JSON.stringify({ ...p, reference: undefined }))
    const parent = s('getParentOfSymbolForChecker', { symbol: p.reference })
    console.log('   parentOfSymbol:', parent && { name: parent.name, flags: parent.flags, decl: parent.declarations })
    for (const location of p.declarations ?? []) {
      const declared = s('getSymbolOfDeclarationForChecker', { location })
      console.log('   symbolOfDeclaration:', declared && { name: declared.name, flags: declared.flags, parent: declared.parent })
      const declParent = declared && s('getParentOfSymbolForChecker', { symbol: declared.reference })
      console.log('   its parent:', declParent && { name: declParent.name, flags: declParent.flags, decl: declParent.declarations })
    }
    console.log('   tags:', JSON.stringify(s('getJsDocTags', { symbol: p.reference })))
  }
}
api.close()

