58	/// The components of `output`, in output order.
59	pub fn targets_of(output: &ExtractionOutput) -> Vec<Target> {
60	    output
61	        .components
62	        .iter()
63	        .map(|(key, entry)| Target {
64	            key: key.clone(),
65	            file_path: entry.file_path.clone(),
66	            display_name: entry.display_name.clone(),
67	            exports: entry.exports.clone(),
68	            described: entry
69	                .props
70	                .values()
71	                .filter(|prop| !prop.description.is_empty())
72	                .map(|prop| prop.name.clone())
73	                .collect(),
74	            // The whole-project merge leaves `@types/react`'s props to the inheritance layers.
