80	/// One whole-project request to the checker: the components to answer for, and how to reach `tsc`. Built with
81	/// [`SemanticRequest::new`] and answered by [`resolve`].
82	#[derive(Debug, Clone)]
83	pub struct SemanticRequest {
84	    /// Where `tsc` finds `node_modules`; its `--cwd`, and where the search for `typescript` starts.
85	    pub project_root: Utf8PathBuf,
86	    /// A tsconfig whose compiler options the checker uses (read with `parseConfigFile`); with none, a default set.
87	    pub tsconfig: Option<Utf8PathBuf>,
88	    /// An explicit `tsc` binary, instead of `node_modules/typescript/bin/tsc` above `project_root`.
89	    pub tsc_path: Option<Utf8PathBuf>,
90	    /// The components to ask about.
91	    pub targets: Vec<Target>,
92	    /// Bound on each request, and on the `tsc` start-up handshake.
93	    pub request_timeout: Duration,
94	    /// The `typescript` versions the checker may report; one that is not among them is a start-up failure.
95	    pub expected_versions: &'static [&'static str],
96	    /// Write every request and its answer here as JSON, to refresh the replay fixture the tests use.
97	    pub record_to: Option<Utf8PathBuf>,
98	    /// Environment for the `tsc` process; the tests use it to pick a replay scenario.
99	    pub extra_env: Vec<(String, String)>,
100	    /// Ask the checker about a component's props, and about the members of each type, last to first. The answer must
101	    /// not change: no id the checker hands out, and so no order of queries, may show in it. The tests set this.
102	    pub reverse_queries: bool,
