123	/// Resolves the request's components with the checker. Blocks; builds its own single-threaded runtime, so it must
124	/// not be called from inside one.
125	pub fn resolve(request: SemanticRequest) -> SemanticOutcome {
126	    let runtime = match tokio::runtime::Builder::new_current_thread().enable_all().build() {
127	        Ok(runtime) => runtime,
128	        Err(error) => return SemanticOutcome::unavailable(format!("could not start an async runtime: {error}")),
129	    };
130	    runtime.block_on(run(request))
131	}
